// Normaliza tanto chamadas do webhook do CRM quanto chamadas internas do EV-00.
// O fluxo usa dois modos: iniciar a avaliacao ou registrar a resposta do botao.
const entrada = $input.first().json ?? {};
const textos = $('Textos da avaliacao').first().json;
const evento = entrada.evento ?? entrada.body ?? entrada;
const payload = evento.payload ?? evento;
const modoInformado = String(evento.modo ?? evento.acao ?? '').trim().toUpperCase();
const respostaBotao = payload.avaliacao_resposta ?? evento.avaliacao_resposta ?? {};
const modo = modoInformado || (respostaBotao.id ? 'REGISTRAR_RESPOSTA' : 'INICIAR_AVALIACAO');

const somenteDigitos = (valor) => String(valor ?? '').replace(/\D/g, '');
const normalizarWaIdTemporario = (valor) => {
  const digits = somenteDigitos(valor);
  if (!digits.startsWith('55') || digits.length !== 13) return digits;
  const assinante = digits.slice(4);
  if (assinante.length === 9 && assinante[0] === '9' && /^[6-9]/.test(assinante[1])) {
    return digits.slice(0, 4) + assinante.slice(1);
  }
  return digits;
};
const normalizarTexto = (valor) => String(valor ?? '').trim().normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase();
const lerBooleano = (valor) => {
  if (typeof valor === 'boolean') return valor;
  const texto = String(valor ?? '').trim().toLowerCase();
  if (['true', '1', 'sim', 's', 'yes'].includes(texto)) return true;
  if (['false', '0', 'nao', 'não', 'n', 'no'].includes(texto)) return false;
  return null;
};
const listarConfiguracao = (valor) => String(valor ?? '').split(',').map((item) => normalizarTexto(item)).filter(Boolean);
const statusElegiveis = listarConfiguracao(textos.status_finalizacao_elegiveis);
const operacoesMassa = listarConfiguracao(textos.operacoes_finalizacao_massa);
const statusFinalizacao = normalizarTexto(payload.status_finalizacao ?? payload.status ?? evento.status_finalizacao ?? evento.status);
const operacao = normalizarTexto(payload.operacao ?? payload.tipo_operacao ?? evento.operacao ?? evento.tipo_operacao);
const statusElegivel = statusElegiveis.includes(statusFinalizacao);
const finalizacaoEmMassa = lerBooleano(payload.finalizacao_em_massa ?? payload.finalizacaoEmMassa ?? evento.finalizacao_em_massa ?? evento.finalizacaoEmMassa) === true
  || operacoesMassa.includes(operacao);

return [{ json: {
  modo,
  status_finalizacao: statusFinalizacao,
  status_elegivel: statusElegivel,
  operacao,
  finalizacao_em_massa: finalizacaoEmMassa,
  atendimento_id: String(payload.atendimento_id ?? payload.atendimentoId ?? evento.atendimento_id ?? evento.atendimentoId ?? '').trim(),
  lead_id: String(payload.lead_id ?? payload.leadId ?? evento.lead_id ?? evento.leadId ?? '').trim(),
  atendente_id: String(payload.atendente_id ?? payload.atendenteId ?? evento.atendente_id ?? evento.atendenteId ?? '').trim(),
  wa_id: normalizarWaIdTemporario(payload.wa_id ?? payload.waId ?? payload.telefone ?? evento.wa_id ?? evento.waId ?? evento.telefone),
  phone_number_id: String($('Textos da avaliacao').first().json.phone_number_id_meta ?? '').trim(),
  mensagem_id: String(payload.mensagem_id ?? payload.mensagemId ?? evento.mensagem_id ?? evento.mensagemId ?? '').trim(),
  avaliacao_resposta: {
    id: String(respostaBotao.id ?? '').trim(),
    titulo: String(respostaBotao.titulo ?? respostaBotao.title ?? '').trim()
  },
  avaliacao_cache_json: String(evento.avaliacao_cache_json ?? '').trim()
} }];

// A avaliacao so inicia quando o CRM liberar o toggle na configuracao.
// Tambem bloqueia finalizacao em massa e atendimentos sem responsavel humano.
const evento = $('Normalizar evento avaliacao').first().json;
const textos = $('Textos da avaliacao').first().json;
const config = $('Buscar configuracao automacao').first().json ?? {};
const parametros = Array.isArray(config.parametros) ? config.parametros : [];
const lerBooleano = (valor) => {
  const texto = String(valor ?? '').trim().toLowerCase();
  if (['true', '1', 'sim', 'ativo', 'habilitado', 'on'].includes(texto)) return true;
  if (['false', '0', 'nao', 'não', 'inativo', 'desabilitado', 'off'].includes(texto)) return false;
  return null;
};
const chavesAceitas = String(textos.toggle_avaliacao_chaves ?? '').split(',').map((item) => item.trim()).filter(Boolean);
const parametro = parametros.find((item) => chavesAceitas.includes(String(item.chave ?? '').trim()));
const habilitada = lerBooleano(parametro?.valor) === true;
const temResponsavelHumano = Boolean(evento.atendente_id);
const camposObrigatoriosOk = Boolean(evento.status_elegivel && evento.atendimento_id && temResponsavelHumano && evento.wa_id);
let motivoBloqueio = '';
if (!habilitada) motivoBloqueio = 'AVALIACAO_DESABILITADA_OU_TOGGLE_AUSENTE';
else if (evento.finalizacao_em_massa) motivoBloqueio = 'FINALIZAR_TODOS_NAO_DISPARA_AVALIACAO';
else if (!temResponsavelHumano) motivoBloqueio = 'SEM_RESPONSAVEL_HUMANO_NAO_DISPARA_AVALIACAO';
else if (!camposObrigatoriosOk) motivoBloqueio = 'DADOS_OBRIGATORIOS_AUSENTES';

return [{ json: {
  ...evento,
  avaliacao_habilitada: habilitada,
  toggle_chave: String(parametro?.chave ?? ''),
  tem_responsavel_humano: temResponsavelHumano,
  pode_enviar: Boolean(habilitada && !evento.finalizacao_em_massa && camposObrigatoriosOk),
  motivo_bloqueio: motivoBloqueio
} }];

// Monta os botoes da Meta e o contexto que ficara no Redis ate a resposta do lead.
const evento = $('Checar toggle avaliacao').first().json;
const textos = $('Textos da avaliacao').first().json;
const phoneNumberId = String(textos.phone_number_id_meta ?? '').trim();
if (!phoneNumberId) throw new Error('PHONE_NUMBER_ID_META_NAO_CONFIGURADO');
const contexto = {
  atendimento_id: evento.atendimento_id,
  lead_id: evento.lead_id,
  atendente_id: evento.atendente_id,
  wa_id: evento.wa_id,
  phone_number_id: phoneNumberId,
  iniciado_em: new Date().toISOString()
};

return [{ json: {
  ...evento,
  phone_number_id: phoneNumberId,
  redis_key_wa: String(textos.redis_key_prefixo_wa ?? '') + evento.wa_id,
  redis_key_lead: evento.lead_id ? String(textos.redis_key_prefixo_lead ?? '') + evento.lead_id : String(textos.redis_key_prefixo_lead_sem_id ?? '') + evento.wa_id,
  redis_valor: JSON.stringify(contexto),
  payload_meta: {
    messaging_product: 'whatsapp',
    recipient_type: 'individual',
    to: evento.wa_id,
    type: 'interactive',
    interactive: {
      type: 'button',
      body: { text: String(textos.texto_pergunta_avaliacao ?? '') },
      footer: { text: String(textos.texto_rodape_avaliacao ?? '') },
      action: {
        buttons: [
          { type: 'reply', reply: { id: String(textos.botao_ruim_id ?? ''), title: String(textos.botao_ruim ?? '') } },
          { type: 'reply', reply: { id: String(textos.botao_bom_id ?? ''), title: String(textos.botao_bom ?? '') } },
          { type: 'reply', reply: { id: String(textos.botao_otimo_id ?? ''), title: String(textos.botao_otimo ?? '') } }
        ]
      }
    }
  }
} }];

const dados = $('Preparar botoes avaliacao').first().json;
const meta = $('Enviar botoes avaliacao pela Meta').first().json;
return [{ json: {
  executado: true,
  codigo: 'AVALIACAO_SOLICITADA',
  atendimento_id: dados.atendimento_id,
  lead_id: dados.lead_id,
  atendente_id: dados.atendente_id,
  whatsapp_message_id: String(meta.messages?.[0]?.id ?? '')
} }];

const dados = $('Checar toggle avaliacao').first().json;
return [{ json: {
  executado: false,
  codigo: dados.motivo_bloqueio || 'AVALIACAO_NAO_ENVIADA',
  atendimento_id: dados.atendimento_id,
  lead_id: dados.lead_id,
  status_finalizacao: dados.status_finalizacao
} }];

// Confere a resposta do botao e recupera do Redis o atendimento/atendente corretos.
// Se o cliente responder texto livre durante a avaliacao, encerramos sem gravar nota.
const evento = $('Normalizar evento avaliacao').first().json;
const cache = JSON.parse(evento.avaliacao_cache_json || '{}');
const textos = $('Textos da avaliacao').first().json;
const notaRuim = Number(textos.nota_ruim);
const notaBom = Number(textos.nota_bom);
const notaOtimo = Number(textos.nota_otimo);
if (![notaRuim, notaBom, notaOtimo].every(Number.isFinite)) throw new Error('NOTAS_AVALIACAO_NAO_CONFIGURADAS');
const mapaNotas = {
  [String(textos.botao_ruim_id ?? '')]: { nota: notaRuim, comentario: String(textos.botao_ruim ?? '') },
  [String(textos.botao_bom_id ?? '')]: { nota: notaBom, comentario: String(textos.botao_bom ?? '') },
  [String(textos.botao_otimo_id ?? '')]: { nota: notaOtimo, comentario: String(textos.botao_otimo ?? '') }
};
const escolha = mapaNotas[evento.avaliacao_resposta.id] ?? null;

const atendimentoId = String(cache.atendimento_id ?? evento.atendimento_id ?? '').trim();
const atendenteId = String(cache.atendente_id ?? evento.atendente_id ?? '').trim();
const leadId = String(cache.lead_id ?? evento.lead_id ?? '').trim();
const waId = String(cache.wa_id ?? evento.wa_id ?? '').trim();
const phoneNumberId = String(cache.phone_number_id ?? textos.phone_number_id_meta ?? '').trim();
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

if (escolha && !uuid.test(atendimentoId)) throw new Error('ATENDIMENTO_ID_INVALIDO_PARA_AVALIACAO');
if (escolha && !uuid.test(atendenteId)) throw new Error('ATENDENTE_ID_INVALIDO_PARA_AVALIACAO');

return [{ json: {
  resposta_valida: Boolean(escolha),
  atendimento_id: atendimentoId,
  atendente_id: atendenteId,
  lead_id: leadId,
  wa_id: waId,
  phone_number_id: phoneNumberId,
  nota: escolha?.nota ?? null,
  comentario: escolha?.comentario ?? String(textos.comentario_sem_nota ?? ''),
  redis_key_wa: String(textos.redis_key_prefixo_wa ?? '') + waId,
  redis_key_lead: leadId ? String(textos.redis_key_prefixo_lead ?? '') + leadId : String(textos.redis_key_prefixo_lead_sem_id ?? '') + waId
} }];

const validada = $('Validar resposta avaliacao').first().json;
const registro = $('Salvar avaliacao no Postgres').first().json;
return [{ json: {
  executado: true,
  codigo: 'AVALIACAO_REGISTRADA',
  atendimento_id: validada.atendimento_id,
  atendente_id: validada.atendente_id,
  nota: validada.nota,
  registro_criado: Boolean(registro.criado),
  avaliacao_id: String(registro.id ?? '')
} }];

const dados = $('Validar resposta avaliacao').first().json;
return [{ json: {
  executado: true,
  codigo: 'AVALIACAO_ENCERRADA_SEM_NOTA',
  atendimento_id: dados.atendimento_id,
  atendente_id: dados.atendente_id,
  nota: null
} }];

// Trata o 409 do CRM como idempotencia: a avaliacao ja existe e o fluxo pode continuar.
const resposta = $('Enviar avaliacao ao CRM').first().json ?? {};
const erro = resposta.error ?? {};
const statusCode = Number(resposta.statusCode ?? resposta.httpCode ?? erro.statusCode ?? erro.httpCode ?? 0);
if (statusCode >= 400 && statusCode !== 409) {
  throw new Error('ERRO_AO_REGISTRAR_AVALIACAO_NO_CRM_' + statusCode);
}
return [{ json: {
  crm_avaliacao_processada: statusCode !== 409,
  crm_avaliacao_idempotente: statusCode === 409,
  crm_status_code: statusCode
} }];
